script:
(function () {
  'use strict';
  // Fuel maths in US units (miles, gallons, mpg, $/gallon).
  //   Trip cost:     miles (x2 for a round trip) / mpg = gallons; gallons x price = cost;
  //                  cost per mile = price / mpg; cost per person = cost / people.
  //   Fuel economy:  mpg = miles / gallons; cost per mile = price / mpg (if a price is given).
  //   Fuel budget:   gallons = budget / price; miles = gallons x mpg.
  // Verified (Node scratch test): 300 mi at 25 mpg and $3.50/gal -> 12 gal, $42.00, $0.14/mile,
  // $14.00 per 100 miles; round trip of 150 mi each way, 2 people -> $21.00 each; 412 mi on
  // 13.7 gal -> 30.07 mpg; $50 at $3.25/gal and 28 mpg -> 15.38 gal, 430.8 miles.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var money3 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 3, maximumFractionDigits: 3 });
  var n1 = new Intl.NumberFormat('en-US', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
  var n2 = new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function num(id) {
    var s = String(document.getElementById(id).value).trim();
    if (s === '') return NaN;
    var v = Number(s);
    return isFinite(v) ? v : NaN;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function show(id, on) { document.getElementById(id).hidden = !on; }

  function tripCost(miles, mpg, price, people) {
    var gallons = miles / mpg, cost = gallons * price;
    return { gallons: gallons, cost: cost, perPerson: cost / people, perMile: price / mpg, per100: price / mpg * 100 };
  }
  function economy(miles, gallons, price) {
    var mpg = miles / gallons;
    return { mpg: mpg, cost: gallons * price, perMile: price / mpg, per100: price / mpg * 100 };
  }
  function budgetRange(budget, price, mpg) {
    var gallons = budget / price;
    return { gallons: gallons, miles: gallons * mpg };
  }

  var LABELS = {
    trip: ['Trip fuel cost', 'Fuel needed', 'Cost per mile', 'Cost per person'],
    mpg: ['Fuel economy', 'Fuel cost', 'Cost per mile', 'Cost per 100 miles'],
    budget: ['Miles you can drive', 'Gallons you can buy', 'Cost per mile', 'Cost per 100 miles']
  };

  function blank(msg) {
    var error = document.getElementById('fuError');
    error.hidden = !msg;
    error.textContent = msg || '';
    ['fuMain', 'fuSecond', 'fuThird', 'fuFourth'].forEach(function (id) { set(id, '–'); });
    set('fuNote', '');
  }

  function update() {
    var mode = document.getElementById('fuMode').value;
    if (!LABELS[mode]) mode = 'trip';
    show('fuTripInputs', mode === 'trip');
    show('fuMpgInputs', mode === 'mpg');
    show('fuBudgetInputs', mode === 'budget');
    show('fuSharedMpg', mode !== 'mpg');
    var l = LABELS[mode];
    set('fuMainLabel', l[0]); set('fuSecondLabel', l[1]); set('fuThirdLabel', l[2]); set('fuFourthLabel', l[3]);
    blank('');
    var price = num('fuPrice');

    if (mode === 'trip') {
      var miles = num('fuMiles'), mpg = num('fuMpgIn'), people = num('fuPeople');
      var round = document.getElementById('fuRound').checked;
      if ([miles, mpg, price, people].some(isNaN) || miles < 0 || mpg <= 0 || price < 0 ||
          people < 1 || Math.floor(people) !== people || miles > 1e7 || mpg > 1000 || price > 100 || people > 100) {
        return blank('Enter a distance of 0 or more, fuel economy above 0 mpg, a fuel price from $0 to $100 and 1 to 100 people.');
      }
      var dist = round ? miles * 2 : miles;
      var t = tripCost(dist, mpg, price, people);
      set('fuMain', money.format(t.cost));
      set('fuSecond', n2.format(t.gallons) + ' gal');
      set('fuThird', money3.format(t.perMile));
      set('fuFourth', money.format(t.perPerson));
      set('fuNote', 'Based on ' + n1.format(dist) + ' miles' + (round ? ' (round trip)' : '') + ' at ' + n1.format(mpg) +
        ' mpg. Fuel costs ' + money.format(t.per100) + ' per 100 miles.');
    } else if (mode === 'mpg') {
      var driven = num('fuDriven'), gallons = num('fuGallons');
      if ([driven, gallons].some(isNaN) || driven <= 0 || gallons <= 0 || driven > 1e7 || gallons > 1e6) {
        return blank('Enter the miles driven and the gallons used, both above 0.');
      }
      var havePrice = !isNaN(price) && price > 0 && price <= 100;
      if (!isNaN(price) && (price < 0 || price > 100)) return blank('Enter a fuel price from $0 to $100, or leave it empty.');
      var e = economy(driven, gallons, havePrice ? price : 0);
      set('fuMain', n2.format(e.mpg) + ' mpg');
      set('fuSecond', havePrice ? money.format(e.cost) : '–');
      set('fuThird', havePrice ? money3.format(e.perMile) : '–');
      set('fuFourth', havePrice ? money.format(e.per100) : '–');
      set('fuNote', 'That is ' + n2.format(gallons / driven * 100) + ' gallons per 100 miles.' +
        (havePrice ? '' : ' Add the fuel price to see the cost per mile.'));
    } else {
      var budget = num('fuBudget'), mpgB = num('fuMpgIn');
      if ([budget, mpgB, price].some(isNaN) || budget < 0 || mpgB <= 0 || price <= 0 || budget > 1e7 || mpgB > 1000 || price > 100) {
        return blank('Enter a budget of $0 or more, fuel economy above 0 mpg and a fuel price above $0 (up to $100).');
      }
      var b = budgetRange(budget, price, mpgB);
      set('fuMain', n1.format(b.miles) + ' mi');
      set('fuSecond', n2.format(b.gallons) + ' gal');
      set('fuThird', money3.format(price / mpgB));
      set('fuFourth', money.format(price / mpgB * 100));
      set('fuNote', money.format(budget) + ' of fuel at ' + money.format(price) + ' a gallon and ' + n1.format(mpgB) + ' mpg.');
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('fuForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
